<script setup lang="ts">
import { ref, computed, onMounted, onActivated } from 'vue'
import { api } from './api'
import { featureLabels } from './literatureState'
import { loadClinicalReferences, retainRuleSelection } from './clinicalReferences'
import { blankVisit, canDecide, visitPayload, type VisitDraft } from './visitState'
const patients=ref<any[]>([]), visits=ref<any[]>([]), rules=ref<any[]>([]), evidence=ref<any[]>([]), timeline=ref<any[]>([])
const researchEntries=ref<any[]>([])
const symptomTerms=computed(()=>Array.from(new Set(researchEntries.value.flatMap((r:any)=>r.features.map((f:any)=>f.key)))).sort())
const literature=computed(()=>analysis.value?.result?.literature_candidates||[])
const patientId=ref(''), newCode=ref(''), selectedVisit=ref(''), draft=ref<VisitDraft>(blankVisit('')), analysis=ref<any>(null)
const saved=ref(''), error=ref(''), notice=ref(''), busy=ref(false), baseRule=ref(''), modifications=ref<string[]>([])
const decision=ref('adopt'), notes=ref(''), finalFormula=ref('[]'), lastDecision=ref<any>(null), sourcePage=ref<any>(null)
const fingerprint=computed(()=>JSON.stringify(draft.value))
const dirty=computed(()=>fingerprint.value!==saved.value)
const decisionAllowed=computed(()=>canDecide(analysis.value,draft.value,dirty.value))
const candidates=computed(()=>analysis.value?.result?.candidates||[])
const usedEvidence=computed(()=>{const ids=new Set(candidates.value.flatMap((c:any)=>c.evidence_ids||[]));return (analysis.value?.evidence_snapshot||evidence.value).filter((e:any)=>ids.has(e.id))})
const publishedPatterns=computed(()=>rules.value.filter(r=>r.status==='published'&&r.kind==='pattern'))
const publishedMods=computed(()=>rules.value.filter(r=>r.status==='published'&&r.kind==='modification'&&(!baseRule.value||r.base_formula_id===rules.value.find(x=>x.id===baseRule.value)?.formula_id)))
const states:Record<string,string>={matched:'规则条件匹配',not_matched:'不满足',pending:'信息不足',conflict:'事实冲突',not_applicable:'不适用'}
function displayTime(value:string){return new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})}
function pretty(value:unknown){return JSON.stringify(value,null,2)}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function refreshPatients(){patients.value=(await api.request('/patients')).items}
async function patientChanged(){visits.value=patientId.value?(await api.request(`/visits?patient_id=${encodeURIComponent(patientId.value)}`)).items:[];timeline.value=patientId.value?(await api.request(`/patients/${patientId.value}/timeline`)).items:[];startVisit()}
function startVisit(previous?:string){draft.value=blankVisit(patientId.value,previous);saved.value=JSON.stringify(draft.value);selectedVisit.value='';analysis.value=null;lastDecision.value=null;baseRule.value='';modifications.value=[]}
async function createPatient(){if(!newCode.value.trim())throw Error('请填写模拟病例代号');const p=await api.post('/patients',{code:newCode.value,notes:''});await refreshPatients();patientId.value=p.id;newCode.value='';await patientChanged();notice.value='病例已创建；首次访次事实为空。'}
async function loadVisit(){if(!selectedVisit.value)return;const v=await api.request(`/visits/${selectedVisit.value}`);draft.value={id:v.id,revision:v.revision,patient_id:v.patient_id,previous_visit_id:v.previous_visit_id,chief_complaint:v.chief_complaint,facts:v.facts,context:v.context,clinician:v.clinician};saved.value=JSON.stringify(draft.value);analysis.value=v.analyses?.[0]||null;lastDecision.value=v.decisions?.[0]||null;finalFormula.value=pretty(analysis.value?.result?.formula||[])}
async function saveVisit(){if(!patientId.value||!draft.value.clinician.trim())throw Error('请选择病例并填写医生');if(draft.value.facts.some(f=>!f.key.trim()))throw Error('事实术语不能为空');const v=draft.value.id?await api.put(`/visits/${draft.value.id}`,visitPayload(draft.value)):await api.post('/visits',visitPayload(draft.value));draft.value={...draft.value,...v};saved.value=JSON.stringify(draft.value);visits.value=(await api.request(`/visits?patient_id=${patientId.value}`)).items;selectedVisit.value=v.id;timeline.value=(await api.request(`/patients/${patientId.value}/timeline`)).items;notice.value='当次事实已保存；请重新运行分析。'}
async function analyze(){if(dirty.value||!draft.value.id)throw Error('请先保存当次事实');const sent=fingerprint.value;const result=await api.post(`/visits/${draft.value.id}/analyze`,{expected_revision:draft.value.revision,base_rule_id:baseRule.value||null,modification_ids:modifications.value});if(sent!==fingerprint.value)throw Error('分析期间事实发生变更，结果未载入；请保存并重新分析');analysis.value=result;lastDecision.value=null;finalFormula.value=pretty(result.result?.modifications?.formula||result.result?.formula||candidates.value.find((c:any)=>c.rule_id===baseRule.value)?.formula||[]);notice.value='规则分析已完成；请逐项核对缺项与风险覆盖。'}
function literatureExample(){draft.value.facts=['头痛','发热','恶风','项背强'].map(key=>({key,state:'present' as const,verified:true,source:'clinician' as const,scope:'current' as const,raw:'文献对照的合成病例，非真实患者'}));draft.value.facts.push({key:'汗出',state:'absent',verified:true,source:'clinician',scope:'current',subject:'patient'});draft.value.chief_complaint='文献对照合成病例：仅研究症候与原文，不作临床结论';notice.value='已加载文献对照合成草稿；须保存后分析。'}
function addFact(){draft.value.facts.push({key:'',state:'unknown',verified:false,raw:'',source:'clinician',scope:'current',subject:'patient'})}
function synthetic(){draft.value.facts=[{key:'demo_cold',state:'present',verified:true,source:'clinician',scope:'current',subject:'patient',raw:'合成算法演示：存在'},{key:'demo_sweat',state:'absent',verified:true,source:'patient',scope:'current',raw:'合成算法演示：明确否定'},{key:'demo_thirst',state:'absent',verified:true,source:'patient',scope:'current'},{key:'demo_emergency',state:'unknown',verified:false,source:'clinician',scope:'current',subject:'patient'},{key:'demo_old',state:'present',verified:true,source:'patient',scope:'history',raw:'合成既往事实，不参与当次判断'}];draft.value.chief_complaint='仅算法验证的合成病例，无临床含义';notice.value='已加载合成事实草稿，未自动保存。'}
async function recordDecision(){if(!decisionAllowed.value)throw Error('当前分析已过期或事实未保存，请重新分析');if(!draft.value.clinician.trim()||!notes.value.trim())throw Error('医生及决定说明不能为空');const payload:any={decision:decision.value,clinician:draft.value.clinician,notes:notes.value};if(decision.value==='modify'){payload.final_formula=JSON.parse(finalFormula.value);if(!Array.isArray(payload.final_formula))throw Error('最终方药必须为Drug数组');}lastDecision.value=await api.post(`/analyses/${analysis.value.id}/decision`,payload);timeline.value=(await api.request(`/patients/${patientId.value}/timeline`)).items;notice.value='医生决定已独立保存；修改方案已由服务端重新核查。'}
async function showSource(e:any){sourcePage.value=await api.request(`/documents/${e.document_id}/pages/${e.physical_page}`)}
onMounted(()=>run(refreshPatients))
onActivated(()=>run(async()=>{researchEntries.value=(await api.request('/research')).items;const refs=await loadClinicalReferences(api);rules.value=refs.rules;evidence.value=refs.evidence;const next=retainRuleSelection(refs.rules,baseRule.value,modifications.value);baseRule.value=next.baseRule;modifications.value=next.modifications;if(analysis.value?.rule_snapshot?.some((r:any)=>!refs.rules.some((current:any)=>current.id===r.id&&current.status==='published')))analysis.value.stale=true}))
</script>
<template><section aria-label="接诊与复诊"><div class="panel case-toolbar"><label>病例代号<select v-model="patientId" :disabled="busy" @change="run(patientChanged)"><option value="">选择病例</option><option v-for="p in patients" :value="p.id" :key="p.id">{{p.code}}</option></select></label><label>新病例代号<input v-model="newCode" :disabled="busy" placeholder="使用代号，勿填身份信息"></label><el-button :loading="busy" @click="run(createPatient)">创建病例</el-button><label>已存访次<select v-model="selectedVisit" :disabled="busy" @change="run(loadVisit)"><option value="">新访次</option><option v-for="v in visits" :key="v.id" :value="v.id">{{displayTime(v.created_at)}} · v{{v.revision}}</option></select></label><el-button :disabled="!patientId||busy" @click="startVisit()">新建初诊</el-button><el-button :disabled="!draft.id||busy" @click="startVisit(draft.id)">新建复诊</el-button></div>
<el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="notice" :title="notice" type="success" :closable="false"/>
<div class="clinic-grid"><div class="panel facts-panel"><div class="section-head"><h2>01 当次事实</h2><el-tag :type="dirty?'warning':'info'">{{dirty?'草稿有修改':draft.id?`已存 v${draft.revision}`:'尚未保存'}}</el-tag></div><p class="hint">{{draft.previous_visit_id?'复诊事实从空开始；既往信息见下方时间线。':'只有已核实的当前事实参与规则判断。'}}未知不等于否定。</p><label>接诊医生<input v-model="draft.clinician" :disabled="busy"></label><label>当次主诉<textarea v-model="draft.chief_complaint" rows="2" :disabled="busy"></textarea></label><div class="two-fields"><label>年龄（岁）<input v-model.number="draft.context.age_years" type="number" min="0" :disabled="busy"></label><label>妊娠状态<select v-model="draft.context.pregnancy" :disabled="busy"><option value="unknown">未知 / 未核</option><option value="yes">是</option><option value="no">否</option></select></label></div><label>过敏史（每行一项，空不代表已排除）<textarea :value="draft.context.allergies.join('\n')" @input="draft.context.allergies=($event.target as HTMLTextAreaElement).value.split('\n').filter(Boolean)" rows="2" :disabled="busy"></textarea></label><label>现用药（每行一项）<textarea :value="draft.context.medications.join('\n')" @input="draft.context.medications=($event.target as HTMLTextAreaElement).value.split('\n').filter(Boolean)" rows="2" :disabled="busy"></textarea></label>
<datalist id="symptom-terms"><option v-for="term in symptomTerms" :key="term" :value="term" /></datalist><article v-for="(f,i) in draft.facts" :key="i" class="fact-card"><div class="section-head"><strong>事实 {{i+1}}</strong><button class="text-link" :disabled="busy" @click="draft.facts.splice(i,1)">删除</button></div><label>症状或体征<input v-model="f.key" list="symptom-terms" :disabled="busy"></label><div class="two-fields"><label>事实主体<select v-model="f.subject" :disabled="busy"><option value="patient">患者本人</option><option value="family">家属</option><option value="other">其他人</option><option value="unknown">主体待核</option></select></label><label>状态<select v-model="f.state" :disabled="busy"><option value="present">存在</option><option value="absent">明确否定</option><option value="unknown">未知</option><option value="conflict">冲突待核</option></select></label><label>时间范围<select v-model="f.scope" :disabled="busy"><option value="current">当前</option><option value="history">既往</option></select></label></div><label>原始描述<textarea v-model="f.raw" rows="2" :disabled="busy"></textarea></label><div class="two-fields"><label>来源<select v-model="f.source" :disabled="busy"><option value="patient">患者自述</option><option value="clinician">医生观察</option><option value="test">检查资料</option></select></label><label>观察时间（ISO8601）<input v-model="f.observed_at" placeholder="未核留空" :disabled="busy"></label></div><div class="two-fields"><label>数值 / 值<select :value="typeof f.value" @change="f.value=($event.target as HTMLSelectElement).value==='number'?0:''" :disabled="busy"><option value="string">文字</option><option value="number">数值</option><option v-if="f.value==null" value="undefined">未录入</option></select><input v-if="typeof f.value==='number'" type="number" v-model.number="f.value" :disabled="busy"><input v-else v-model="f.value" :disabled="busy"></label><label>单位<input v-model="f.unit" :disabled="busy"></label></div><label class="check"><input type="checkbox" v-model="f.verified" :disabled="busy">医生已核实该条事实</label></article><div class="empty" v-if="!draft.facts.length">当次暂无事实，请逐条录入。</div><div class="button-row"><el-button :disabled="busy" @click="addFact">＋ 添加事实</el-button><el-button :disabled="busy" @click="literatureExample">文献对照示例（合成）</el-button><el-button :disabled="busy" @click="synthetic">算法边界示例</el-button></div><el-button type="primary" :loading="busy" :disabled="!patientId" @click="run(saveVisit)">保存当次事实</el-button></div>
<div class="panel compare-panel"><div class="section-head"><h2>02 候选与决定</h2><el-tag>确定性规则</el-tag></div><label>医生选择基础方规则<select v-model="baseRule" :disabled="busy" @change="modifications=[];analysis=null"><option value="">未选择 · 先比较候选</option><option v-for="r in publishedPatterns" :key="r.id" :value="r.id">{{r.title}} · v{{r.version}}{{r.synthetic?' · 合成':''}}</option></select></label><label>加减研究规则（可多选）<select v-model="modifications" multiple :disabled="busy" @change="analysis=null"><option v-for="r in publishedMods" :key="r.id" :value="r.id">{{r.title}}</option></select></label><el-button type="primary" :loading="busy" :disabled="!draft.id||dirty" @click="run(analyze)">运行规则分析</el-button><p v-if="analysis&&!decisionAllowed" class="warning" role="alert">旧分析仅供追溯。当次事实已变更，请保存并重新分析。</p><p class="empty" v-if="!analysis">保存事实后运行分析。不会以支持项补足必要条件。</p><template v-if="analysis"><p class="hint">分析 {{analysis.id}} · 访次版本 {{analysis.visit_revision}}</p><el-alert v-if="analysis.result?.urgent" type="error" title="合成危险信号命中：停止生成可用方药；须优先核查。" :closable="false"/><section class="literature-comparison"><h3>倪氏课程与经典条文对照</h3><p class="warning">仅对照原文记录项，必要/充分条件与临床适用性尚待合作医师审核。按来源页序展示，不表示优先选方。以下不是已发布的选方或用药建议。</p><p v-if="!literature.length" class="hint">暂无已核实症候命中首批研究条目；可补充四诊或检索全库原文。</p><article v-for="r in literature" :key="r.id" class="candidate"><h3>{{r.formula_name}} <el-tag type="warning">待临床审核</el-tag></h3><p><b>支持：</b>{{featureLabels(r,r.supporting).join('、')||'无已核实支持项'}}</p><p><b>反证：</b>{{featureLabels(r,r.opposing).join('、')||'无列出项'}}</p><p><b>未知：</b>{{featureLabels(r,r.unknown).join('、')||'无列出项'}}；<b>冲突：</b>{{featureLabels(r,r.conflicting).join('、')||'无列出项'}}</p><blockquote>{{r.classic_quote}}</blockquote><p>鉴别追问：{{r.differential_questions.join('；')}}</p><p v-if="r.modification_action">原文加减：{{r.modification_action.base}}，加{{r.modification_action.add.join('、')||'无列出'}}，去{{r.modification_action.remove.join('、')||'无列出'}}；剂量与适用条件待核。</p><details><summary>倪氏讲解归纳及校勘问题</summary><p>{{r.ni_comment_summary}}</p><p v-for="n in r.quality_notes" :key="n">{{n}}</p></details><a :href="r.pdf_url" target="_blank" rel="noopener">原件 · 物理页 {{r.physical_pages.join('、')}} ↗</a></article></section><h3>已发布规则的确定性判定</h3><article v-for="c in candidates" :key="c.rule_id" class="candidate"><div class="section-head"><h3>{{c.title}}</h3><el-tag :type="c.status==='matched'?'success':c.status==='conflict'?'danger':'warning'">{{states[c.status]||c.status}}</el-tag></div><p><b>缺项：</b>{{c.missing?.join('、')||'无列出项'}}</p><p><b>冲突：</b>{{c.conflicts?.join('、')||'无列出项'}}</p><details><summary>必要、支持与反证逐条件轨迹</summary><h4>必要条件</h4><pre>{{pretty(c.required)}}</pre><h4>支持条件</h4><pre>{{pretty(c.support)}}</pre><h4>排除 / 反证</h4><pre>{{pretty(c.excluded)}}</pre></details><details><summary>该规则基础方及原单位</summary><pre>{{pretty(c.formula)}}</pre></details></article><div class="risk-box"><h3>风险与覆盖核查</h3><pre>{{pretty(analysis.result?.safety)}}</pre><p class="warning">缺安全库、核查缺项或数据未覆盖均不表示安全。</p></div><details><summary>加减结果、鉴别问题与完整审计轨迹</summary><pre>{{pretty(analysis.result)}}</pre></details><hr><h3>医生独立决定</h3><label>处理方式<select v-model="decision" :disabled="busy"><option value="adopt">采用研究结果</option><option value="modify">修改后记录（重新核查）</option><option value="reject">驳回</option></select></label><label v-if="decision==='modify'">最终方药 Drug[]（保留炮制、量、单位、计量基础、证据）<textarea v-model="finalFormula" rows="8" spellcheck="false" :disabled="busy"></textarea></label><label>决定说明<textarea v-model="notes" rows="3" :disabled="busy"></textarea></label><el-button type="primary" :loading="busy" :disabled="!decisionAllowed" @click="run(recordDecision)">保存医生决定</el-button><div v-if="lastDecision" class="decision-box"><h4>已记录的医生决定</h4><pre>{{pretty(lastDecision)}}</pre></div></template></div>
<div class="panel sources-panel"><h2>03 原文依据</h2><p class="hint">原文证据、规则判断及模型提议分别呈现。</p><article v-for="e in usedEvidence" :key="e.id" class="evidence-card"><el-tag size="small">证据 · {{e.kind}}</el-tag><blockquote>{{e.quote}}</blockquote><small>{{e.id}} · 物理页{{e.physical_page}}</small><div class="button-row"><button class="text-link" @click="run(()=>showSource(e))">阅读来源页</button><a :href="`/api/documents/${encodeURIComponent(e.document_id)}/pdf#page=${e.physical_page}`" target="_blank" rel="noopener">PDF ↗</a></div></article><p v-if="!usedEvidence.length" class="empty">当前分析尚无已发布规则的原文证据；文献研究条目在候选区提供原件入口。合成规则不代表医学知识。</p><details v-if="sourcePage" open><summary>来源页 {{sourcePage.physical_page}} · {{sourcePage.review_status}}</summary><img class="original-page-image" :src="`/api/documents/${sourcePage.document_id}/pages/${sourcePage.physical_page}/image`" :alt="`来源原件物理页${sourcePage.physical_page}`"><pre class="source-text">{{sourcePage.corrected_text||sourcePage.raw_text}}</pre><small class="warning">{{sourcePage.warning}}</small></details></div></div>
<div class="panel timeline"><div class="section-head"><h2>复诊时间线</h2><span class="hint">历史事实仅供核对，变化不自动归因为疗效。</span></div><p v-if="!timeline.length" class="empty">选择病例后显示访次与独立决定。</p><details v-for="v in timeline" :key="v.id"><summary>{{displayTime(v.created_at)}} · {{v.previous_visit_id?'复诊':'初诊'}} · v{{v.revision}} · {{v.chief_complaint}}</summary><pre>{{pretty({facts:v.facts,analyses:v.analyses,decisions:v.decisions,model_supplements:v.model_supplements})}}</pre></details></div></section></template>





